import { cacheLife, cacheTag } from 'next/cache'
import { getPosts } from '@/lib/api'

export default async function Home() {
  'use cache'
  // Cache for 1 hour; stale/expire inherit from the `default` profile.
  cacheLife({ revalidate: 3600 })
  // Tag the entry so it can be invalidated on-demand via revalidateTag('posts').
  cacheTag('posts')

  const posts = await getPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            {post.title} — {post.author}
          </li>
        ))}
      </ul>
    </main>
  )
}

